'use strict';

// Generated by Clause Sonnet 5.5 / Refactored by HellXCore
// Reports about devices, on Linux, from /sys and /proc:
//
//   usb   the removable drives mounted (USB sticks and SD cards, not external hard disks)
//         
//   plug  the last device plugged in or out: { n, in, name, class }. n counts them, `in` is true for
//         plugged in, `class` like (WPD, AudioEndpoint, Camera, Image, HIDClass, Keyboard, Mouse,
//         Bluetooth, DiskDrive, USB), which her reactions go by.
//
// USB devices only, which are in /sys/bus/usb. A phone shows up as several devices one after the other,
// so after a change the list is looked at again of what is new, the one that says the most is the one.

const fs = require('node:fs');
const path = require('node:path');

// "Galaxy S21" says more than "USB Composite Device"
const VAGUE = /composite|hub|concentrateur|input device|hid|mass storage|stockage|g.n.ri|virtu|num.rat|interface|host|h.te|bus|port|endpoint|service|profil|protocol|p.riph.rique|dispositivo/i;

const score = (cls, name) => {
  let s = cls === 'WPD' ? 6
    : cls === 'AudioEndpoint' ? 5
      : cls === 'Camera' || cls === 'Image' ? 4
        : ['HIDClass', 'Keyboard', 'Mouse'].includes(cls) ? 3
          : cls === 'Bluetooth' ? 2 : 1;
  if (VAGUE.test(name)) s -= 4;
  return s;
};

// of [{ name, class }]: the one that says the most, the first on a tie; none without a name
function best(list) {
  let top = -Infinity;
  let pick = null;
  for (const d of list) {
    if (!d.name) continue;
    const s = score(d.class, d.name);
    if (s > top) {
      top = s;
      pick = d;
    }
  }
  return pick;
}

const read = (file) => {
  try {
    return fs.readFileSync(file, 'utf8').trim();
  } catch {
    return '';
  }
};

// The Windows PnP class of a USB device, from the classes of its interfaces ([{ cls, protocol }],
// hex as /sys writes them). A phone first (it also offers storage), a webcam before its microphone.
function classify(interfaces) {
  const has = (code) => interfaces.some((i) => i.cls === code);
  if (has('06')) return 'WPD'; // still image / PTP: phones, cameras
  if (has('0e')) return 'Camera';
  if (has('01')) return 'AudioEndpoint';
  const hid = interfaces.find((i) => i.cls === '03');
  if (hid) return hid.protocol === '01' ? 'Keyboard' : hid.protocol === '02' ? 'Mouse' : 'HIDClass';
  if (has('e0')) return 'Bluetooth';
  if (has('08')) return 'DiskDrive';
  return 'USB';
}

// Map id -> { name, class } of the USB devices there are (not hubs, not their interfaces)
function usbDevices(sysfs = '/sys') {
  const dir = path.join(sysfs, 'bus', 'usb', 'devices');
  let entries = [];
  try {
    entries = fs.readdirSync(dir);
  } catch {
    return new Map();
  }
  const out = new Map();
  for (const id of entries) {
    if (id.includes(':') || /^usb\d+$/.test(id)) continue; // an interface, or a root hub
    const base = path.join(dir, id);
    if (read(path.join(base, 'bDeviceClass')) === '09') continue; // a hub
    const interfaces = entries.filter((e) => e.startsWith(`${id}:`)).map((e) => ({
      cls: read(path.join(dir, e, 'bInterfaceClass')).toLowerCase(),
      protocol: read(path.join(dir, e, 'bInterfaceProtocol')),
    }));
    out.set(id, { name: read(path.join(base, 'product')), class: classify(interfaces) });
  }
  return out;
}

// "/run/media/u/MY\040STICK" -> "/run/media/u/MY STICK" (/proc/mounts escapes spaces and the like)
const unescapeMount = (s) => s.replace(/\\([0-7]{3})/g, (_, o) => String.fromCharCode(parseInt(o, 8)));

// The names of the removable drives mounted, in the order they are mounted
function removableDrives({ sysfs = '/sys', mounts = '/proc/self/mounts' } = {}) {
  const names = [];
  for (const line of read(mounts).split('\n')) {
    const [device, mountpoint] = line.split(' ');
    if (!device || !device.startsWith('/dev/') || !mountpoint) continue;
    const name = path.basename(device);
    let disk = name;
    try {
      const real = fs.realpathSync(path.join(sysfs, 'class', 'block', name));
      if (fs.existsSync(path.join(real, 'partition'))) disk = path.basename(path.dirname(real)); // sdb1 -> sdb
    } catch {
      continue; // not a block device of this system
    }
    const removable = read(path.join(sysfs, 'block', disk, 'removable')) === '1' || read(path.join(sysfs, 'block', disk, 'device', 'type')) === 'SD';
    const label = path.basename(unescapeMount(mountpoint));
    if (removable && label && !names.includes(label)) names.push(label);
  }
  return names;
}

// Looks at the USB devices and the removable drives now and then; onChange() when usb or plug changed.
function createDevices({
  sysfs = '/sys', mounts = '/proc/self/mounts', intervalMs = 1000, settleMs = 1200, onChange = () => {},
  timers = { setInterval, clearInterval, setTimeout, clearTimeout },
} = {}) {
  let devices = null; // Map id -> { name, class }: the devices as of the last look
  let usb = [];
  let plug = null;
  let plugs = 0;
  let tick = null;
  let settle = null;

  const settled = () => {
    settle = null;
    const now = usbDevices(sysfs);
    const added = [...now].filter(([id]) => !devices.has(id)).map(([, d]) => d);
    const removed = [...devices].filter(([id]) => !now.has(id)).map(([, d]) => d);
    devices = now;
    const plugged = added.length > 0;
    const pick = best(plugged ? added : removed);
    if (!pick) return;
    plugs += 1;
    plug = { n: plugs, in: plugged, name: pick.name, class: pick.class };
    onChange();
  };

  const poll = () => {
    const now = usbDevices(sysfs);
    if (!devices) devices = now; // what was there when she started is not news
    else if (!settle && (now.size !== devices.size || [...now.keys()].some((id) => !devices.has(id)))) {
      settle = timers.setTimeout(settled, settleMs); // a phone shows up as several devices
      settle.unref?.();
    }
    const drives = removableDrives({ sysfs, mounts });
    if (JSON.stringify(drives) !== JSON.stringify(usb)) {
      usb = drives;
      onChange();
    }
  };

  return {
    start() {
      if (tick) return;
      poll();
      tick = timers.setInterval(poll, intervalMs);
      tick.unref?.();
    },
    stop() {
      if (tick) timers.clearInterval(tick);
      if (settle) timers.clearTimeout(settle);
      tick = null;
      settle = null;
    },
    poll,
    snapshot: () => ({ usb: usb.slice(), plug: plug && { ...plug } }),
  };
}

module.exports = { createDevices, usbDevices, removableDrives, classify, best };
